<?php
require __DIR__.'/app-bootstrap.php';$u=require_admin();require $privateRootPath.'/src/admin_layout.php';
$status=(string)($_GET['status']??'');if(!in_array($status,['open','pending_customer','resolved','closed'],true))$status='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();try{$ticketId=(int)($_POST['ticket_id']??0);$message=trim((string)($_POST['message']??''));$newStatus=(string)($_POST['status']??'open');if($ticketId<1)throw new RuntimeException('Ticket not found.');if(!in_array($newStatus,['open','pending_customer','resolved','closed'],true))throw new RuntimeException('Invalid ticket status.');$pdo->beginTransaction();$pdo->prepare('UPDATE support_tickets SET status=? WHERE id=?')->execute([$newStatus,$ticketId]);if($message!=='')$pdo->prepare('INSERT INTO support_messages(ticket_id,admin_user_id,message) VALUES(?,?,?)')->execute([$ticketId,(int)$u['id'],$message]);$st=$pdo->prepare('SELECT t.subject,u.email FROM support_tickets t JOIN users u ON u.id=t.user_id WHERE t.id=?');$st->execute([$ticketId]);$recipient=$st->fetch();$pdo->commit();if($message!==''&&$recipient){try{send_store_mail((string)$recipient['email'],site_name().' support update #'.$ticketId,(string)$recipient['subject']."\n\n".$message);}catch(Throwable $ignored){error_log('Support reply failed: '.$ignored->getMessage());}}$_SESSION['admin_flash']=['message'=>'Support ticket updated.','error'=>false];}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['admin_flash']=['message'=>$e->getMessage(),'error'=>true];}redirect('admin-support.php'.($status!==''?'?status='.rawurlencode($status):''));}
$where='';$params=[];if($status!==''){$where=' WHERE t.status=?';$params[]=$status;}$st=$pdo->prepare("SELECT t.id,t.subject,t.status,t.priority,t.created_at,t.updated_at,u.display_name,u.email,o.id order_id,COUNT(m.id) message_count FROM support_tickets t JOIN users u ON u.id=t.user_id LEFT JOIN orders o ON o.id=t.order_id LEFT JOIN support_messages m ON m.ticket_id=t.id{$where} GROUP BY t.id ORDER BY FIELD(t.status,'open','pending_customer','resolved','closed'),t.updated_at DESC");$st->execute($params);$tickets=$st->fetchAll();
admin_layout_start('Customer support','support');
?><div class="section-title"><div><span class="kicker">HELP DESK</span><h1>Customer support</h1></div><span><?=count($tickets)?> ticket<?=count($tickets)===1?'':'s'?></span></div><form method="get" class="panel admin-compact-form"><label>Status<select name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['open','pending_customer','resolved','closed'] as $value):?><option value="<?=$value?>" <?=$status===$value?'selected':''?>><?=e(str_replace('_',' ',ucfirst($value)))?></option><?php endforeach;?></select></label></form><?php if(!$tickets):?><section class="panel"><p class="muted">No support tickets match this filter.</p></section><?php else:?><div class="support-admin-list"><?php foreach($tickets as $ticket):$st=$pdo->prepare('SELECT m.*,COALESCE(u.display_name,au.display_name,"Support") sender FROM support_messages m LEFT JOIN users u ON u.id=m.user_id LEFT JOIN users au ON au.id=m.admin_user_id WHERE m.ticket_id=? ORDER BY m.created_at');$st->execute([(int)$ticket['id']]);$messages=$st->fetchAll();?><details class="panel support-ticket"><summary><span><strong>#<?=$ticket['id']?> · <?=e($ticket['subject'])?></strong><small><?=e($ticket['display_name'])?> · <?=e($ticket['email'])?><?php if($ticket['order_id']):?> · Order #<?=$ticket['order_id']?><?php endif;?></small></span><span class="status-badge <?=e((string)$ticket['status'])?>"><?=e(str_replace('_',' ',ucfirst((string)$ticket['status'])))?></span></summary><div class="support-thread"><?php foreach($messages as $message):?><article class="support-message"><strong><?=e($message['sender'])?></strong><small><?=e($message['created_at'])?></small><p><?=nl2br(e($message['message']))?></p></article><?php endforeach;?><form method="post" class="admin-edit-form"><label>Reply<textarea name="message" rows="5" placeholder="Optional reply to the customer"></textarea></label><label>Status<select name="status"><?php foreach(['open','pending_customer','resolved','closed'] as $value):?><option value="<?=$value?>" <?=$ticket['status']===$value?'selected':''?>><?=e(str_replace('_',' ',ucfirst($value)))?></option><?php endforeach;?></select></label><input type="hidden" name="ticket_id" value="<?=$ticket['id']?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button">Save ticket</button></form></div></details><?php endforeach;?></div><?php endif;?><?php admin_layout_end();
